const allItems = $input.all();
const eligible = [];

for (const item of allItems) {
  const row = item.json;
  const rowId = String(row['#'] || '').trim();
  const actor = String(row['Actor'] || '').trim();
  const movie = String(row['Movie (Year)'] || '').trim();
  const dialogue = String(row['Iconic Dialogue'] || '').trim();
  const angle = String(row['Poster Advertising Angle'] || '').trim();
  const status = String(row['Status'] || '').trim().toLowerCase();
  const linkedInDraft = String(row['LinkedIn_Post'] || '').trim();

  if (rowId.length > 0 && dialogue.length > 0 && angle.length > 0 && (status === '' || status === 'pending') && linkedInDraft === '') {
    const rawImageFlag = String(row['Include Image?'] || 'Yes').trim().toLowerCase();
    const includeImageNormalized = (rawImageFlag === 'no' || rawImageFlag === 'false' || rawImageFlag === '0') ? 'No' : 'Yes';

    eligible.push({
      json: {
        '#': rowId,
        Actor: actor,
        'Movie (Year)': movie,
        'Iconic Dialogue': dialogue,
        'Poster Advertising Angle': angle,
        'Include Image?': includeImageNormalized,
        LinkedIn_Mention: String(row['LinkedIn_Mention'] || '').trim(),
        Facebook_Mention: String(row['Facebook_Mention'] || '').trim(),
        Instagram_Mention: String(row['Instagram_Mention'] || '').trim(),
        Status: 'Processing'
      }
    });
    break;
  }
}

return eligible;

const inputRow = $('03_Filter_And_Sanitize_Input').first().json;
const rowId = inputRow['#'];
const actor = inputRow['Actor'];
const movie = inputRow['Movie (Year)'];
const rawDialogue = inputRow['Iconic Dialogue'];
const rawAngle = inputRow['Poster Advertising Angle'];
const includeImage = inputRow['Include Image?'] || 'Yes';
const liMention = inputRow['LinkedIn_Mention'] || '';
const fbMention = inputRow['Facebook_Mention'] || '';
const igMention = inputRow['Instagram_Mention'] || '';

const cleanDialogue = rawDialogue.replace(/^["']+|["']+$/g, '').trim();
const cleanAngle = rawAngle.replace(/^["']+|["']+$/g, '').trim();

const apiKey = String($env.OPENROUTER_API_KEY || '').replace(/[<>/"'\s]/g, '');
const baseUrl = 'https://openrouter.ai/api/v1';
const configuredModel = String($env.OPENROUTER_MODEL || 'google/gemma-4-31b-it:free').trim();

if (!apiKey || apiKey === 'undefined') {
  throw new Error('OPENROUTER_API_KEY is missing from environment variables.');
}

const combinedPrompt = [
  'You are an International Executive Creative Director and Copywriter for Creyotech (Website Design Agency).',
  `Invent an original, breathtaking 1024x1024 (1K resolution, 1:1 square) commercial advertisement inspired by '${movie}' (${actor}).`,
  'CREATIVE DIRECTION RULES:',
  '1. Invent a movie-specific symbolic metaphor, bespoke color palette, dramatic lighting, and sophisticated composition tailored to this movie.',
  '2. BANNED CLICHES: ZERO human faces, NO film reels, NO clapperboards, NO movie projectors.',
  `3. Keep Iconic Dialogue EXACTLY word-for-word: "${cleanDialogue}"`,
  `4. Keep Poster Advertising Angle EXACTLY word-for-word: "${cleanAngle}"`,
  '5. In image_gen_prompt, instruct Nano Banana 2.1 to render these 3 exact text strings on the poster:',
  `   - Primary Hero Headline: "${cleanDialogue}"`,
  `   - Secondary Callout Pill: "${cleanAngle}"`,
  '   - Footer Brand Badge: "WEBSITE DESIGN | CREYOTECH"',
  '6. Return ONLY raw valid JSON (no markdown blocks):',
  '{ "linkedin_post": "...", "facebook_post": "...", "instagram_post": "...", "image_gen_prompt": "...", "image_description": "..." }',
  '',
  `Row: ${rowId} | Actor: ${actor} | Movie: ${movie} | LinkedIn_Mention: ${liMention} | Facebook_Mention: ${fbMention} | Instagram_Mention: ${igMention}`
].join('\n');

function extractCleanJson(rawText) {
  let cleaned = String(rawText || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  return JSON.parse(cleaned);
}

let candidateModels = [configuredModel, 'nvidia/nemotron-3-ultra:free', 'nvidia/nemotron-3.5-super-vl:free', 'google/gemma-4-26b-a4b-it:free', 'openrouter/free'];
let parsedOutput = null;
let usedModel = null;

for (const modelId of candidateModels) {
  try {
    const chatResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/chat/completions`,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://zero-touch-n8n.onrender.com',
        'X-Title': 'Zero-Touch Creative Director'
      },
      body: {
        model: modelId,
        messages: [{ role: 'user', content: combinedPrompt }],
        temperature: 0.8
      },
      json: true,
      timeout: 45000
    });

    const content = chatResp?.choices?.[0]?.message?.content;
    if (!content) continue;
    const candidateJson = extractCleanJson(content);
    if (candidateJson.linkedin_post && candidateJson.facebook_post && candidateJson.instagram_post) {
      parsedOutput = candidateJson;
      usedModel = modelId;
      break;
    }
  } catch (err) {
    continue;
  }
}

if (!parsedOutput) {
  parsedOutput = {
    linkedin_post: `"${cleanDialogue}"\n\nInspired by ${movie}, your digital presence deserves world-class engineering.\n\n🎯 ${cleanAngle}\n\n#WebsiteDesign #Creyotech #DigitalStrategy`,
    facebook_post: `"${cleanDialogue}" ✨\n\n🎯 ${cleanAngle}\n\nUpgrade your website with Creyotech today! #Creyotech #WebsiteDesign`,
    instagram_post: `"${cleanDialogue}" 🔥\n\n🎯 ${cleanAngle}\n\n🚀 DM Creyotech for world-class website design! #Creyotech #WebsiteDesign`,
    image_gen_prompt: `Create a breathtaking 1024x1024 (1K resolution, 1:1 square) international luxury technology advertisement inspired by '${movie}' (${actor}). Use a powerful symbolic 3D metaphor, dramatic lighting, and sophisticated editorial composition (no human faces, no film reels, no clapperboards). Render exact text: Primary Headline: "${cleanDialogue}", Secondary Callout: "${cleanAngle}", Footer Badge: "WEBSITE DESIGN | CREYOTECH".`,
    image_description: `${movie} (${actor}) Ad Poster: "${cleanDialogue}" - ${cleanAngle}`
  };
  usedModel = 'fallback-template';
}

function enforceVerbatimAndMention(postText, dialogueStr, angleStr, mentionStr) {
  let finalPost = String(postText || '').trim();
  if (!finalPost.toLowerCase().includes(dialogueStr.toLowerCase())) {
    finalPost = `"${dialogueStr}"\n\n` + finalPost;
  }
  if (!finalPost.toLowerCase().includes(angleStr.toLowerCase())) {
    finalPost = finalPost + `\n\n🎯 ${angleStr}`;
  }
  if (mentionStr && !finalPost.toLowerCase().includes(mentionStr.toLowerCase())) {
    finalPost = finalPost + `\n\ncc: ${mentionStr}`;
  }
  return finalPost;
}

const liPost = enforceVerbatimAndMention(parsedOutput.linkedin_post, cleanDialogue, cleanAngle, liMention);
const fbPost = enforceVerbatimAndMention(parsedOutput.facebook_post, cleanDialogue, cleanAngle, fbMention);
const igPost = enforceVerbatimAndMention(parsedOutput.instagram_post, cleanDialogue, cleanAngle, igMention);

const imgPrompt = (includeImage.toLowerCase() === 'no') ? '' : String(parsedOutput.image_gen_prompt || '');
const imgDesc = (includeImage.toLowerCase() === 'no') ? '' : String(parsedOutput.image_description || `${movie} (${actor}) Poster: "${cleanDialogue}"`);

return [
  {
    json: {
      ...inputRow,
      ai_model_used: usedModel,
      Status: 'Draft',
      linkedin_post: liPost,
      facebook_post: fbPost,
      instagram_post: igPost,
      image_gen_prompt: imgPrompt,
      image_description: imgDesc,
      Image_URL: ''
    }
  }
];

const item = $input.first().json;
const prompt = item.image_gen_prompt;

const airouterKey = String($env.AIROUTER_API_KEY || '').replace(/[<>/"'\s]/g, '');
const airouterBase = String($env.AIROUTER_BASE_URL || 'https://api.airouter.in/v1').replace(/\/+$/, '');
const airouterModel = String($env.AIROUTER_IMAGE_MODEL || 'google/gemini-nano-banana-2.1').trim();
const imgbbKey = String($env.IMGBB_API_KEY || '').replace(/[<>/"'\s]/g, '');

if (!airouterKey) throw new Error('AIROUTER_API_KEY is missing.');
if (!imgbbKey) throw new Error('IMGBB_API_KEY is missing.');

let base64Image = null;
let directImageUrl = null;

function parseImageCandidate(val) {
  if (!val || typeof val !== 'string') return;
  const trimmed = val.trim();
  if (trimmed.startsWith('data:image')) {
    base64Image = trimmed.split(',')[1];
  } else if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
    directImageUrl = trimmed;
  } else if (trimmed.length > 256) {
    base64Image = trimmed;
  }
}

const airouterResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${airouterBase}/chat/completions`,
  headers: {
    'Authorization': `Bearer ${airouterKey}`,
    'Content-Type': 'application/json',
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
    'HTTP-Referer': 'https://zero-touch-n8n.onrender.com',
    'X-Title': 'ZeroTouch-NanoBanana-Engine'
  },
  body: {
    model: airouterModel,
    messages: [{ role: 'user', content: prompt }],
    modalities: ['image', 'text']
  },
  json: true,
  timeout: 420000
});

const msg = airouterResp?.choices?.[0]?.message || {};
const imagesArr = msg.images || [];

for (const imgEntry of imagesArr) {
  if (typeof imgEntry === 'string') {
    parseImageCandidate(imgEntry);
  } else if (imgEntry && typeof imgEntry === 'object') {
    const nestedUrl = (imgEntry.image_url && typeof imgEntry.image_url === 'object')
      ? imgEntry.image_url.url
      : imgEntry.image_url;
    parseImageCandidate(nestedUrl || imgEntry.url || imgEntry.b64_json || imgEntry.data || imgEntry.image);
  }
  if (base64Image || directImageUrl) break;
}

if (!base64Image && !directImageUrl && typeof msg.content === 'string') {
  const dataMatch = msg.content.match(/(data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+)/);
  if (dataMatch) {
    parseImageCandidate(dataMatch[1]);
  } else {
    const urlMatch = msg.content.match(/(https?:\/\/[^\s\)"'>]+)/);
    if (urlMatch) parseImageCandidate(urlMatch[1]);
  }
}

if (!base64Image && !directImageUrl) {
  throw new Error('AIRouter did not return a recognizable image payload.');
}

const imagePayload = base64Image || directImageUrl;
const formBody = `key=${encodeURIComponent(imgbbKey)}&image=${encodeURIComponent(imagePayload)}&name=nanobanana_1k_${Date.now()}`;

const uploadResp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.imgbb.com/1/upload',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: formBody,
  json: true,
  timeout: 120000
});

const publicUrl = uploadResp?.data?.url || directImageUrl;
if (!publicUrl) {
  throw new Error('ImgBB failed to return a public image URL.');
}

return [
  {
    json: {
      ...item,
      Image_URL: publicUrl
    }
  }
];

const item = $input.first().json;
return [
  {
    json: {
      ...item,
      image_gen_prompt: '',
      image_description: '',
      Image_URL: ''
    }
  }
];

const raw = $input.first().json;
const body = (raw && raw.body && typeof raw.body === 'object') ? raw.body : raw;

return [
  {
    json: {
      '#': String(body['#'] || '').trim(),
      Status: String(body.Status || 'Draft').trim(),
      'Include Image?': String(body['Include Image?'] || 'Yes').trim(),
      linkedin_post: String(body.LinkedIn_Post || body.linkedin_post || ''),
      facebook_post: String(body.Facebook_Post || body.facebook_post || ''),
      instagram_post: String(body.Instagram_Post || body.instagram_post || ''),
      image_gen_prompt: String(body.Image_Gen_Prompt || body.image_gen_prompt || ''),
      image_description: String(body.Image_Description || body.image_description || ''),
      Image_URL: String(body.Image_URL || ''),
      Error_Message: String(body.Error_Message || '')
    }
  }
];
